import{_ as t,o as n,c as a,ae as i}from"./chunks/framework.B2FZg54p.js";const o="/heidrun/experiments/web-doc-by-ai/documentation_images/split_and_resize_panes/split_controls.svg",s="/heidrun/experiments/web-doc-by-ai/documentation_images/split_and_resize_panes/selected_pane.svg",b=JSON.parse('{"title":"Split and resize panes","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/split_and_resize_panes.md","filePath":"documentation/split_and_resize_panes.md"}'),r={name:"documentation/split_and_resize_panes.md"};function p(h,e,l,d,c,u){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="split-and-resize-panes" tabindex="-1">Split and resize panes <a class="header-anchor" href="#split-and-resize-panes" aria-label="Permalink to &quot;Split and resize panes&quot;">​</a></h1><p>Split a terminal pane, adjust the space between panes, and choose which pane receives keyboard input.</p><h2 id="split-a-pane" tabindex="-1">Split a pane <a class="header-anchor" href="#split-a-pane" aria-label="Permalink to &quot;Split a pane&quot;">​</a></h2><p>Use a pane in the selected tab that is outside the column of pinned panes. If the pane you want to split is pinned, select <strong>Unpin the pane</strong> in its header in the column of pinned panes. If another tab is selected, select the pane’s own tab to see it there again. The <strong>Unpin the pane</strong> control is in the pinned pane’s header, beside <strong>Go to tab</strong>. Then use <strong>Split right</strong> or <strong>Split down</strong> in the pane header. The pane whose header you use is the one that splits, and the new pane appears adjacent to it.</p><ol><li>Find the pane you want to split in the selected tab, outside the column of pinned panes. If it is pinned, unpin it first, then select its own tab if needed.</li><li>In that pane&#39;s header, select <strong>Split right</strong> to place a pane beside it, or <strong>Split down</strong> to place a pane below it.</li><li>Check that the new pane appears beside the pane whose header you selected, or below it when you chose <strong>Split down</strong>.</li></ol><p><img src="'+o+'" alt="The pane header in context and a close view identifying Split right and Split down"></p><h2 id="resize-panes" tabindex="-1">Resize panes <a class="header-anchor" href="#resize-panes" aria-label="Permalink to &quot;Resize panes&quot;">​</a></h2><p>When two panes touch, the thin dividing line between them is the resize control. Drag the line left or right to change the widths of panes, or up or down to change their heights.</p><ol><li>Move the pointer to the thin line between the panes until the line responds to the pointer.</li><li>Drag the line in the direction you want to change the panes.</li><li>When the panes have the sizes you want, release the dividing line.</li></ol><p>To share the space evenly between the adjoining panes, you can double-click the dividing line. This resets their split to equal sizes.</p><p>The dividing line is between panes; the edge between the viewport and a sidebar is not a dividing line between panes.</p><h2 id="choose-a-pane-for-keyboard-input" tabindex="-1">Choose a pane for keyboard input <a class="header-anchor" href="#choose-a-pane-for-keyboard-input" aria-label="Permalink to &quot;Choose a pane for keyboard input&quot;">​</a></h2><p>The pane with keyboard focus receives typed input. Click inside the terminal that should receive your typing; when the viewport shows several panes, the selected pane&#39;s header has a tinted background.</p><p><img src="'+s+'" alt="Three panes after splitting, with the selected pane&#39;s tinted header identified"></p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="No dividing line appears"><h3 id="no-dividing-line-appears" tabindex="-1">No dividing line appears <a class="header-anchor" href="#no-dividing-line-appears" aria-label="Permalink to &quot;No dividing line appears&quot;">​</a></h3><p><strong>Cause</strong>: A tab with one pane has no internal dividing line.</p><p><strong>Solution</strong>:</p><ol><li>In the pane header, select <strong>Split right</strong> or <strong>Split down</strong>.</li><li>Drag the thin line between the panes that appear.</li></ol><p><strong>Check</strong>: A thin line between the panes is visible and responds when you drag it.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/tabs.html">Create, select and rename tabs</a>: to open or switch to another tab.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/pane_focus_history.html">Go back and forward through the panes that had the focus</a>: to return to a pane you used earlier.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/pin_a_pane.html">Pin and unpin a pane</a>: to keep a pane visible while switching tabs.</li></ul>',18)])])}const _=t(r,[["render",p]]);export{b as __pageData,_ as default};
